-- ═══════════════════════════════════════════════════════════════════════════
-- Story Hunters Guild — Fabula Ultima reference data (classes/skills/spells/
-- arcana/inventions/equipment/status effects/heroic skills/rituals & projects)
-- ═══════════════════════════════════════════════════════════════════════════
-- Generated by scripts/seed-fu-reference-data.ts — do not hand-edit the insert
-- statements below, re-run the script instead. Run AFTER 033_shg_rol_quest_
-- note_document.sql. Pure read-only reference/lookup data: shg_service (the
-- app's server-side role) gets full CRUD like every other table, RLS is
-- enabled with no policies so anon/authenticated can't touch it directly —
-- same posture as shg_rol_guild_status (027_shg_rol_guild_status.sql).

create table if not exists shg_fu_class (
  id                  text primary key,
  name                text not null,
  also_known_as       text[] not null default '{}',
  description         text not null,
  roleplay_questions  text[] not null default '{}',
  free_benefits       jsonb not null,
  sort_order          int not null default 0
);

create table if not exists shg_fu_skill (
  id           uuid primary key default gen_random_uuid(),
  class_id     text not null references shg_fu_class(id) on delete cascade,
  name         text not null,
  max_level    int not null,
  description  text not null,
  sort_order   int not null default 0,
  unique (class_id, name)
);
create index if not exists shg_fu_skill_class_idx on shg_fu_skill (class_id);

create table if not exists shg_fu_spell (
  id           uuid primary key default gen_random_uuid(),
  class_id     text not null references shg_fu_class(id) on delete cascade,
  name         text not null,
  offensive    boolean not null,
  mp_cost      text not null,
  target       text not null,
  duration     text not null,
  description  text not null,
  opportunity  text,
  sort_order   int not null default 0,
  unique (class_id, name)
);
create index if not exists shg_fu_spell_class_idx on shg_fu_spell (class_id);

create table if not exists shg_fu_arcanum (
  id              uuid primary key default gen_random_uuid(),
  class_id        text not null references shg_fu_class(id) on delete cascade,
  name            text not null,
  domains         text[] not null,
  merge_effect    text not null,
  dismiss_effect  text not null,
  sort_order      int not null default 0,
  unique (class_id, name)
);
create index if not exists shg_fu_arcanum_class_idx on shg_fu_arcanum (class_id);

create table if not exists shg_fu_invention_type (
  id              text primary key,
  class_id        text not null references shg_fu_class(id) on delete cascade,
  name            text not null,
  also_known_as   text[] not null default '{}',
  description     text not null,
  tiers           jsonb not null,
  sort_order      int not null default 0
);
create index if not exists shg_fu_invention_type_class_idx on shg_fu_invention_type (class_id);

create table if not exists shg_fu_weapon (
  id          text primary key,
  name        text not null,
  category    text not null,
  cost        int,
  martial     boolean not null default false,
  handedness  text not null,
  range_type  text not null,
  accuracy    text not null,
  damage      text not null,
  notes       text not null default '',
  sort_order  int not null default 0
);

create table if not exists shg_fu_armor_shield (
  id              text primary key,
  name            text not null,
  item_type       text not null,
  cost            int not null,
  martial         boolean not null default false,
  defense         jsonb not null,
  magic_defense   jsonb not null,
  initiative      int not null default 0,
  notes           text not null default '',
  sort_order      int not null default 0
);

create table if not exists shg_fu_inventory_item (
  id          text primary key,
  name        text not null,
  category    text not null,
  ip_cost     int not null,
  effect      text not null,
  sort_order  int not null default 0
);

create table if not exists shg_fu_status_effect (
  id           text primary key,
  name         text not null,
  affects      text[] not null,
  description  text not null,
  sort_order   int not null default 0
);

create table if not exists shg_fu_heroic_skill (
  id           text primary key,
  name         text not null,
  requirement  text,
  description  text not null,
  sort_order   int not null default 0
);

create table if not exists shg_fu_ritual_discipline (
  id             text primary key,
  name           text not null,
  magic_check    text not null,
  example_uses   text not null,
  sort_order     int not null default 0
);
create table if not exists shg_fu_ritual_potency (
  id              text primary key,
  name            text not null,
  mp_base_cost    int not null,
  difficulty      int not null,
  examples        text not null,
  sort_order      int not null default 0
);
create table if not exists shg_fu_ritual_area (
  id              text primary key,
  name            text not null,
  mp_multiplier   numeric not null,
  examples        text not null,
  sort_order      int not null default 0
);

create table if not exists shg_fu_project_potency (
  id            text primary key,
  name          text not null,
  base_cost     int not null,
  capabilities  text not null,
  sort_order    int not null default 0
);
create table if not exists shg_fu_project_area (
  id               text primary key,
  name             text not null,
  cost_multiplier  numeric not null,
  examples         text not null,
  sort_order       int not null default 0
);
create table if not exists shg_fu_project_uses (
  id               text primary key,
  name             text not null,
  cost_multiplier  numeric not null,
  description      text not null,
  sort_order       int not null default 0
);

grant select, insert, update, delete on
  shg_fu_class, shg_fu_skill, shg_fu_spell, shg_fu_arcanum, shg_fu_invention_type,
  shg_fu_weapon, shg_fu_armor_shield, shg_fu_inventory_item, shg_fu_status_effect,
  shg_fu_heroic_skill, shg_fu_ritual_discipline, shg_fu_ritual_potency, shg_fu_ritual_area,
  shg_fu_project_potency, shg_fu_project_area, shg_fu_project_uses
  to shg_service;

alter table shg_fu_class enable row level security;
alter table shg_fu_skill enable row level security;
alter table shg_fu_spell enable row level security;
alter table shg_fu_arcanum enable row level security;
alter table shg_fu_invention_type enable row level security;
alter table shg_fu_weapon enable row level security;
alter table shg_fu_armor_shield enable row level security;
alter table shg_fu_inventory_item enable row level security;
alter table shg_fu_status_effect enable row level security;
alter table shg_fu_heroic_skill enable row level security;
alter table shg_fu_ritual_discipline enable row level security;
alter table shg_fu_ritual_potency enable row level security;
alter table shg_fu_ritual_area enable row level security;
alter table shg_fu_project_potency enable row level security;
alter table shg_fu_project_area enable row level security;
alter table shg_fu_project_uses enable row level security;

