insert into shg_fu_class (id, name, also_known_as, description, roleplay_questions, free_benefits, sort_order) values
('arcanist', 'Arcanist', ARRAY['Avatar', 'Chosen', 'Summoner']::text[], 'Arcanists can fall into a deep trance and temporarily project a considerable portion of their soul outside the body, giving it physical form. Surrounded by this magical shroud, the Arcanist gains a variety of supernatural abilities; these summoned forms are said to be manifestations of the ancestral souls belonging to mythical entities of legend, known as the Arcana. In some worlds, the Arcana are even worshipped as deities.', ARRAY['Where do your powers come from? Are they a gift from your bloodline?', 'Have you ever communicated with an Arcanum, or are they silent and distant?', 'Do people see you as mysterious, powerful, or otherworldly?', 'Are there many practicing your art, or are you the exception?']::text[], '[{"text":"Permanently increase your maximum Mind Points by 5.","statBonus":{"stat":"mp","amount":5}}]'::jsonb, 0),
('chimerist', 'Chimerist', ARRAY['Druid', 'Shapeshifter', 'Wild Mage']::text[], 'Chimerists gather their power from the souls of the monsters and beasts they encounter. By manipulating their inner wild energy, these mages may mimic the magical abilities of monsters and have reached a supernatural understanding of feral creatures. Chimerists frequently rely on their toughness and physical prowess in addition to magic; they are often seen traveling the world in search of rare and enchanted creatures.', ARRAY['Who taught you the art of Chimerism? Is your mentor human or monstrous?', 'Can people and monsters live in harmony, or are they bound to threaten each other?', 'What does your magic look like?', 'Are there many practicing your art, or are you the exception?']::text[], '[{"text":"Permanently increase your maximum Mind Points by 5.","statBonus":{"stat":"mp","amount":5}},{"text":"You may perform Rituals whose effects fall within the Ritualism discipline."}]'::jsonb, 1),
('darkblade', 'Darkblade', ARRAY['Avenger', 'Black Knight', 'Death Knight']::text[], 'Darkblades are somber and powerful warriors who hide a sorrowful past. Due to tragic experiences on the battlefield or in personal life, their souls have developed an affinity for pain and shadow energy. An unlikely hero to say the very least, a Darkblade may now sacrifice their lifeforce to unleash mighty attacks and is able to draw resolve, power and even knowledge from the suffering they experience.', ARRAY['What tragic experience awakened your abilities?', 'Many would regard your powers as evil. How do you feel about them?', 'What do your weapons and fighting style look like?', 'Are there many practicing your art, or are you the exception?']::text[], '[{"text":"Permanently increase your maximum Hit Points by 5.","statBonus":{"stat":"hp","amount":5}},{"text":"Gain the ability to equip martial melee weapons and martial armor.","equipGrant":{"weapons":"melee","armor":true}}]'::jsonb, 2),
('elementalist', 'Elementalist', ARRAY['Battle Mage', 'Geomancer', 'Sorcerer']::text[], 'An Elementalist has learned to channel the souls that flow within the basic elements of creation: Air, Earth, Fire and Water. Some of them develop complex spells to contain the powerful energies of nature; others seek its protection in harmony and communion. Elemental magic can be highly destructive, causing damage and inflicting negative status effects. Due to this, there are many who would covet an Elementalist’s abilities... often for nefarious purposes.', ARRAY['Who trained you in the way of the Elements?', 'Your magic can be devastating... are you afraid of yourself?', 'Elemental magic is often used in war. Did you serve in the military?', 'What does your magic look like?']::text[], '[{"text":"Permanently increase your maximum Mind Points by 5.","statBonus":{"stat":"mp","amount":5}},{"text":"You may perform Rituals whose effects fall within the Ritualism discipline."}]'::jsonb, 3),
('entropist', 'Entropist', ARRAY['Astromancer', 'Chaos Mage', 'Gambler']::text[], 'High above the stars, where their lights do not shine, lies a bottomless void where life and souls wither and transform in unfathomable ways. This realm is a non-reality, an endless expanse of chaos impervious to the laws of time, space, and probability. Entropists refer to this realm as the Cosmos, the Heavens, or quite simply as Lady Luck: they are among the few gifted with the ability to channel its reality-bending energies.', ARRAY['Who taught you to channel the reality-bending powers of the Cosmos?', 'What do you know of the Cosmos? Are they the end of reality, or a new beginning?', 'What does your magic look like?', 'Are there many practicing your art, or are you the exception?']::text[], '[{"text":"Permanently increase your maximum Mind Points by 5.","statBonus":{"stat":"mp","amount":5}},{"text":"You may perform Rituals whose effects fall within the Ritualism discipline."}]'::jsonb, 4),
('fury', 'Fury', ARRAY['Berserker', 'Brawler', 'Viking']::text[], 'Furies never know when to quit. In battle and life they are energetic, determined and often restless. Whatever ideals or desires drive their actions, they will stop at nothing and risk everything in order to achieve them. Some Furies undergo a rigid training in order to control their emotions; others simply see might as the solution to all problems and are constantly on the verge of letting rage get the best of them.', ARRAY['Do you rely on your burning passion, or do you strive to keep it under control?', 'There’s that one thing that always makes you lose it. What is it?', 'In the past, your lack of control had tragic consequences. What have you lost?', 'What do your weapons and fighting style look like?']::text[], '[{"text":"Permanently increase your maximum Hit Points by 5.","statBonus":{"stat":"hp","amount":5}},{"text":"Gain the ability to equip martial melee weapons and martial armor.","equipGrant":{"weapons":"melee","armor":true}}]'::jsonb, 5),
('guardian', 'Guardian', ARRAY['Paladin', 'Soldier', 'Yōjinbō']::text[], 'Proud and selfless, Guardians are individuals who know the value of life... and are willing to sacrifice themselves for a person, nation or ideal they have sworn to protect. They are often extraordinary and impressive individuals, such as valiant soldiers or veterans scarred by a thousand battles. While some Guardians may appear loud and boisterous, many are simply masking the tormented memory of those they failed to protect.', ARRAY['Who or what is it you would gladly give your life to protect?', 'Are you, or have you ever been, the servant of a Lady or Lord? What were they like?', 'What is it you were unable to protect? What have you lost?', 'What are you using as your armor and/or shield?']::text[], '[{"text":"Permanently increase your maximum Hit Points by 5.","statBonus":{"stat":"hp","amount":5}},{"text":"Gain the ability to equip martial armor and martial shields.","equipGrant":{"armor":true,"shields":true}}]'::jsonb, 6),
('loremaster', 'Loremaster', ARRAY['Archivist', 'Sage', 'Scholar']::text[], 'Loremasters are known for their insatiable curiosity and appetite for discovery. They firmly believe that knowledge equates to power, and would often trade all gold in the world for a chance at solving a good mystery. Unfortunately, a majority of Loremasters tend to be aloof and easily distracted, rarely concerning themselves with “pragmatic” matters... to the point of sometimes failing to realize the darker implications of their discoveries.', ARRAY['Who is (or was) your mentor? What is (or was) your relationship with them?', 'Did you attend an academy or college? What kind of people did you meet there?', 'There is this centuries-old mystery you’re obsessed with. What is it?', 'Is it true that some things are better left buried beneath the sands of time?']::text[], '[{"text":"Permanently increase your maximum Mind Points by 5.","statBonus":{"stat":"mp","amount":5}}]'::jsonb, 7),
('orator', 'Orator', ARRAY['Ambassador', 'Diplomat', 'Entertainer']::text[], 'Some are graceful and ever-smiling, others are subtle and witty: Orators are as good at reading someone’s heart as they are at rounding up allies for their cause, sometimes unintentionally. The words of an Orator may rekindle spirits or plunge their opponents into despair: over the centuries, some Orators'' talents have brought entire nations to ruin... and just as many have granted fallen kingdoms a chance to rise from their very ashes.', ARRAY['Do you think everyone can be persuaded? Is it true that everyone has a price?', 'You thought someone was on your side, but they betrayed you. Who are they?', 'How do you feel about manipulating people, even if it is for a good cause?', 'In the past, your words ended up putting you in trouble. What happened?']::text[], '[{"text":"Permanently increase your maximum Mind Points by 5.","statBonus":{"stat":"mp","amount":5}}]'::jsonb, 8),
('rogue', 'Rogue', ARRAY['Bandit', 'Ninja', 'Thief']::text[], 'Be they criminals, rebels or spies, Rogues are more than willing to play dirty in order to get what they want. Rogues are generally quick, witty and elusive: while a few of them are infamous for being mostly concerned with their personal wealth and profit, many see themselves as fighting against injustice, tyranny, or social exclusion. Tragically, it is quite common for Rogues to end up being painted as threats by those same people they fight for.', ARRAY['What drives you? Is it desire, vengeance, or a burning need for freedom?', 'Are you part of a criminal gang or guild, or do you work on your own?', 'Is there a place you can call home? Or is it true that, in the end, we all die alone?', 'What is the most important rule in your personal code?']::text[], '[{"text":"Permanently increase your maximum Inventory Points by 2.","statBonus":{"stat":"ip","amount":2}}]'::jsonb, 9),
('sharpshooter', 'Sharpshooter', ARRAY['Archer', 'Gunslinger', 'Sniper']::text[], 'A majority of Sharpshooters are exceptionally good at dealing with threats from a carefully calculated distance; others are brave, skilled or reckless enough to engage their foes at point-blank. While many of these skilled snipers are battle-hardened soldiers, some have turned to a life of piracy, bounty hunting or banditry. A few have put their abilities at the service of the people, or use them to protect a sacred or forbidden site from intruders.', ARRAY['Some believe arrows and bullets to be a coward''s weapons. What''s your opinion?', 'When caught unprepared, do you improvise or do you retreat?', 'Are you quiet and reserved, confident and cunning, or boisterous and reckless?', 'What do your weapons and fighting style look like?']::text[], '[{"text":"Permanently increase your maximum Hit Points by 5.","statBonus":{"stat":"hp","amount":5}},{"text":"Gain the ability to equip martial ranged weapons and martial shields.","equipGrant":{"weapons":"ranged","shields":true}}]'::jsonb, 10),
('spiritist', 'Spiritist', ARRAY['Healer', 'Priest', 'Witch']::text[], 'Spiritists have developed a powerful connection with the raw aspects of soul: emotion, energy, life, and death. They wield power both miraculous and frightening, and are quite often affiliated with cults or religions. Several worlds see the powers of Spiritism as gifts from a deity or proof that a person''s heart is pure; however, there is no definite proof of these abilities coming from anything but discipline, empathy, and focus.', ARRAY['Where does your magic come from? What are your beliefs concerning life and death?', 'How do you feel about manipulating other people’s emotions and vital energy?', 'What do you think of religion? Are you part of a specific cult, church or institution?', 'What does your magic look like?']::text[], '[{"text":"Permanently increase your maximum Mind Points by 5.","statBonus":{"stat":"mp","amount":5}},{"text":"You may perform Rituals whose effects fall within the Ritualism discipline."}]'::jsonb, 11),
('tinkerer', 'Tinkerer', ARRAY['Alchemist', 'Magitech Engineer', 'Mechanic']::text[], 'Tinkerers possess exceptional ingenuity and are known for their eccentric and marvelous inventions. They travel the world in an endless search for lost theories and ancient machinery, eyes glimmering whenever they witness the wonders of architecture and engineering.

In a way, Tinkerers could be seen as the ultimate dreamers and rebels, challenging the very rules of nature and society in their pursuit of a better future.', ARRAY['Did you learn your craft from someone? What is your relationship with them?', 'What have you lost in the pursuit of progress and innovation?', 'Is your craft something revolutionary, or is it an established field of work?', 'When an item or effect is created through your abilities, what does it look like?']::text[], '[{"text":"Permanently increase your maximum Inventory Points by 2.","statBonus":{"stat":"ip","amount":2}},{"text":"You may initiate Projects."}]'::jsonb, 12),
('wayfarer', 'Wayfarer', ARRAY['Adventurer', 'Explorer', 'Treasure Hunter']::text[], 'Nomads searching for a fabled continent, explorers braving the wilds, grizzled hunters and travelers have one thing in common: they are Wayfarers. While a majority of heroes travel the world during their adventures, Wayfarers live for the journey. They are always eager to visit new places and learn from others. In the eyes of a Wayfarer, the wilderness is neither foe nor an ally, but rather a stern teacher who can reveal many forgotten truths.', ARRAY['What led you to live a life of endless travels? Was it your choice? ...are you tired?', 'Is there a place or person that feels like “home” to you?', 'You have met many people and visited many places. Is there one you can’t forget?', 'You lost something or someone because of your travels. What happened?']::text[], '[{"text":"Permanently increase your maximum Inventory Points by 2.","statBonus":{"stat":"ip","amount":2}}]'::jsonb, 13),
('weaponmaster', 'Weaponmaster', ARRAY['Fighter', 'Rōnin', 'Warrior']::text[], 'Weaponmasters spend years upon years honing their close combat arts. Most of them display remarkable skill with a variety of weapons; others have trained to become one with a specific armament. Many Weaponmasters follow and protect someone out of love or loyalty, but there are also those who tirelessly wander the world seeking worthy opponents, legendary magical weapons, or capable teachers.', ARRAY['What is your relationship with weapons? Are they mere objects, or something more?', 'Is battle something you seek, or something you strive to avoid?', 'Are you, or have you ever been, the servant of a Lady or Lord? What were they like?', 'What do your weapons and fighting style look like?']::text[], '[{"text":"Permanently increase your maximum Hit Points by 5.","statBonus":{"stat":"hp","amount":5}},{"text":"Gain the ability to equip martial melee weapons and martial shields.","equipGrant":{"weapons":"melee","shields":true}}]'::jsonb, 14)
on conflict (id) do nothing;

insert into shg_fu_skill (class_id, name, max_level, description, sort_order) values
('arcanist', 'Arcane Circle', 4, 'After you willingly dismiss an Arcanum on your turn during a conflict (see next page), if that Arcanum had not been summoned during this same turn and you have an arcane weapon equipped, you may immediately perform the Spell action for free. The spell you cast this way must have a total Mind Point cost of【SL × 5】or lower (you must still pay the spell''s MP cost).', 0),
('arcanist', 'Arcane Regeneration', 2, 'When you summon an Arcanum, you immediately recover【SL × 5】Hit Points.', 1),
('arcanist', 'Bind and Summon', 1, 'You may bind Arcana to your soul and summon them later. The Game Master will tell you the details of each binding process when you first encounter the Arcanum in question.

You may use an action and spend 40 Mind Points to summon an Arcanum you have bound: the details of this process are explained on the next page.

If you take this Skill at character creation, you begin play with one Arcanum of your choice already bound to you, chosen from the list on the next pages. Other than that, you may only obtain new Arcana through exploration and story progression.', 2),
('arcanist', 'Emergency Arcanum', 6, 'As long as you are in Crisis, the cost for summoning your Arcana is reduced by 【SL × 5】Mind Points.', 3),
('arcanist', 'Ritual Arcanism', 1, 'You may perform Rituals of the Arcanism discipline, as long as their effects fall within the domains of one or more Arcana you have bound (see next pages).

Arcanism Rituals use【WLP + WLP】for the Magic Check.', 4),
('chimerist', 'Consume', 5, 'After you deal damage to one or more creatures with a spell, if you have an arcane, dagger or flail weapon equipped, you recover【SL × 2】Mind Points.', 0),
('chimerist', 'Feral Speech', 1, 'You can communicate with creatures of the beast, monster and plant Species.', 1),
('chimerist', 'Pathogenesis', 1, 'When you deal damage to one or more creatures with one of your Chimerist spells, each of those creatures that share their Species with the creature you originally learned that spell from suffers poisoned.', 2),
('chimerist', 'Ritual Chimerism', 1, 'You may perform Rituals whose effects fall within the Chimerism discipline. When you acquire this Skill, choose【INS + WLP】or【MIG + WLP】. From now on, your Chimerism Rituals will use the chosen Attributes for the Magic Check.', 3),
('chimerist', 'Spell Mimic', 10, 'When you see a creature belonging to the beast, monster or plant Species cast a spell, you may immediately choose to learn that spell as a Chimerist spell of your own: if you do, record the Species of the creature you learned it from.

When you first acquire this Skill, choose【INS + WLP】or【MIG + WLP】. From now on, your offensive (r) Chimerist spells will use the chosen Attributes for the Magic Check, regardless of the Attributes used by the creature you learned the spell from.

You may have up to【SL + 2】different Chimerist spells memorized this way. If you want to memorize a new Chimerist spell but are already at your limit, you must forget one of your old spells and replace it with the new spell.', 4),
('darkblade', 'Agony', 5, 'After you deal damage to one or more creatures, if you have a Bond towards at least one of those creatures, you may recover【SL × 2】Hit Points and【SL × 2】Mind Points.', 0),
('darkblade', 'Dark Blood', 1, 'As long as you are in Crisis, you have Resistance to dark damage and poison damage.', 1),
('darkblade', 'Heart of Darkness', 1, 'Once per scene upon entering Crisis, you may choose a specific creature you can see that you don''t have a Bond towards. If you do, create a Bond of hatred towards that creature.', 2),
('darkblade', 'Painful Lesson', 3, 'After another creature causes you to lose Hit Points (with an attack, a spell or any other method), you may immediately perform the Study action on that creature (see page 74) for free. If you do, gain a bonus equal to【SL】to your Check.

Remember, you can study the same aspect of a creature only once.', 3),
('darkblade', 'Shadow Strike', 5, 'You have learned to channel your vital force into your attacks. You may use an action to perform a Shadow Strike: roll your current Might die and lose an amount of Hit Points equal to【the number rolled on your Might die】. If this didn''t reduce your Hit Points to 0, you may perform a free attack with a weapon you have equipped: if this attack hits one or more targets, it deals extra damage equal to【SL + the number rolled on your Might die】. However, all damage dealt by this attack becomes dark and its damage type cannot be changed.', 4),
('elementalist', 'Cataclysm', 3, 'When you cast an instantaneous spell, if you have an arcane weapon equipped, you may increase the spell''s total MP cost by up to【SL × 10】Mind Points. If you do so and the spell deals damage to one or more creatures, it will deal 5 extra damage to each creature for every 10 Mind Points by which you increased its total MP cost.', 0),
('elementalist', 'Elemental Magic', 10, 'Each time you acquire this Skill, learn one Elementalist spell (see next two pages). Offensive (r) Elementalist spells use【INS + WLP】for the Magic Check.', 1),
('elementalist', 'Magical Artillery', 3, 'When you cast an offensive (r) spell, if you have an arcane weapon equipped, you gain a bonus to your Magic Check equal to【SL × 2】.', 2),
('elementalist', 'Ritual Elementalism', 1, 'You may perform Rituals whose effects fall within the Elementalism discipline. Elementalism Rituals use【INS + WLP】for the Magic Check.', 3),
('elementalist', 'Spellblade', 4, 'When you cast an offensive (r) spell targeting a single creature, if the spell has a total Mind Point cost of【SL × 10】or lower and you have one or more bow, brawling, dagger, flail, spear or sword weapons equipped, you may choose one of those weapons. If you do, your Magic Check for the spell will use the chosen weapon''s Accuracy Check formula; for instance, the Magic Check for an Elementalist spell cast through a bronze sword (page 131) will be【DEX + MIG】+1 instead of【INS + WLP】.', 4),
('entropist', 'Absorb MP', 5, 'After you suffer damage, you may immediately recover【SL × 2】Mind Points.', 0),
('entropist', 'Entropic Magic', 10, 'Each time you acquire this Skill, learn one Entropist spell (see next two pages).

Offensive (r) Entropist spells use【INS + WLP】for the Magic Check.', 1),
('entropist', 'Lucky Seven', 1, 'You have a lucky number; at the beginning of each session, that number is 7. Once per scene after you perform a Check, you may replace the value shown on one of the dice you rolled with your lucky number (even if this would give an impossible Result, such as a value of 7 on a d6). If you do, the replaced value becomes your new lucky number.', 2),
('entropist', 'Ritual Entropism', 1, 'You may perform Rituals whose effects fall within the Entropism discipline.

Entropism Rituals use【INS + WLP】for the Magic Check.', 3),
('entropist', 'Stolen Time', 4, 'During a conflict, you may use an action to interfere with the flow of time by spending up to【SL × 5】Mind Points. For every 5 Mind Points you spend this way, choose one option: one creature you can see suffers slow; or one creature you can see recovers from slow; or one creature you can see may immediately perform the Equipment action for free; or choose one ally you can see who has yet to take a turn during this round: that ally may take their turn immediately after yours during this round. Each option can only be chosen once per use of this Skill.', 4),
('fury', 'Adrenaline', 5, 'As long as you are in Crisis, you deal【SL × 2】extra damage (be it with attacks, spells, Arcana, items or any other method).', 0),
('fury', 'Frenzy', 1, 'Your Accuracy Checks with brawling, dagger, flail and thrown weapons trigger a critical success if both dice show the same number (and the Check is not a fumble).', 1),
('fury', 'Indomitable Spirit', 4, 'When you spend one or more Fabula Points, you get an additional benefit — choose one option: you recover【SL × 5】Hit Points; or you recover【SL × 5】Mind Points; or you recover from a single status effect of your choice.', 2),
('fury', 'Provoke', 5, 'You may use an action and spend 5 Mind Points to perform an Opposed【MIG + WLP】 Check against a creature you can see — describe how you taunt them! If you succeed, the target suffers enraged and is compelled to focus their attention on you (their attacks and offensive spells must include you among the targets if possible). This compulsion ends if you fall unconscious or leave the scene, if the creature is no longer enraged, or if they are successfully provoked by someone else. You gain a bonus equal to【SL】to your【MIG + WLP】Checks for this Skill.', 3),
('fury', 'Withstand', 5, 'When you perform the Guard action, if you choose not to provide cover to another creature, you recover Hit Points equal to【SL, multiplied by the highest strength among your Bonds】and choose Might or Willpower: you treat the chosen Attribute as being one die size higher (up to a maximum of d12) until the end of your next turn.', 4),
('guardian', 'Bodyguard', 1, 'If you perform the Guard action and choose to provide cover to another creature, that creature gains Resistance to all damage types until the start of your next turn.', 0),
('guardian', 'Defensive Mastery', 5, 'As long as you have a shield or a martial armor equipped, all damage you suffer is reduced by【SL】(applied before damage Affinities).', 1),
('guardian', 'Dual Shieldbearer', 1, 'You may now equip a shield in your main hand slot. As long as you have two shields equipped, you gain the benefits of both items and may treat them as the following combined two-handed melee brawling weapon:

Twin Shields — 【MIG + MIG】 accuracy, 【HR + 5】physical damage. Deals extra damage equal to your【SL】in Defensive Mastery (above).', 2),
('guardian', 'Fortress', 5, 'Permanently increase your maximum Hit Points by【SL × 3】.', 3),
('guardian', 'Protect', 1, 'When another creature is threatened by an attack, spell or other danger, you may take their place (any Checks that are part of the danger will be performed against you; you may declare the use of this Skill before or after the Checks have been made). If the danger already affected you, it affects you twice (resolve both instances separately); you also cannot protect multiple creatures from the same danger. If you use this Skill during a conflict, you cannot use it again until the start of your next turn.', 4),
('loremaster', 'Flash of Insight', 3, 'When you roll a 13 or higher on a Check performed to investigate a creature, item or location — this includes using the Study action during a conflict — you may ask the Game Master up to【SL】questions concerning the subject of your investigation. You may ask these questions immediately or save them for later; whenever you ask one of these questions, the Game Master will answer truthfully and you will describe your character''s deductive process. This Skill may only be used once on the same creature, item or location.', 0),
('loremaster', 'Focused', 5, 'Permanently increase your maximum Mind Points by【SL × 3】. When you perform an Open Check using【INS + INS】, you gain a bonus equal to【SL】on that Check (this only applies to Open Checks).', 1),
('loremaster', 'Knowledge is Power', 1, 'When you perform an Accuracy Check, you may replace one of the Attribute dice with Insight (such as【INS + INS】for a pistol or【INS + MIG】for a waraxe).', 2),
('loremaster', 'Quick Assessment', 6, 'At the start of a conflict, you may spend up to【SL × 5】Mind Points. For every 5 Mind Points you spend this way, choose one option: choose a creature you can see and the GM reveals one of their Traits; or name a damage type and choose a creature you can see, and the GM reveals that creature''s Affinity towards that damage type.', 3),
('loremaster', 'Trained Memory', 1, 'You may perfectly recall the details of any scene you have visited within the past week. You can "go back in time" within your mind in order to examine and investigate such scenes again — your Flash of Insight Skill will apply to these memories as well.', 4),
('orator', 'Condemn', 4, 'You may use an action and spend 5 Mind Points to perform an Opposed【INS + WLP】 Check against a creature that can hear and understand you — describe your accusations! If you succeed, the target loses【SL × 10】Mind Points and suffers dazed or shaken (your choice). You gain a bonus equal to【SL】to your【INS + WLP】Checks for this Skill.', 0),
('orator', 'Encourage', 6, 'During a conflict, you may use an action and spend 5 Mind Points to choose another creature that can hear and understand you. That creature recovers【SL × 5】Hit Points and chooses Dexterity, Insight, Might, or Willpower: they treat the chosen Attribute as being one die size higher (up to a maximum of d12) until the start of your next turn.', 1),
('orator', 'My Trust in You', 2, 'After another Player Character who is able to hear you performs a Check, you may spend 1 Fabula Point and invoke one of their Traits or Bonds in order to let them reroll dice or improve the Result of the Check (following the normal rules). Then, if you have a Bond towards that character, they recover【SL × 10】Mind Points.', 2),
('orator', 'Persuasive', 2, 'When you successfully perform a Check to fill or erase sections of a Clock, if your approach relied on charm, diplomacy, deception or intimidation, you may spend up to 【SL × 20】Mind Points. If you do, fill or erase an additional section of that Clock for every 20 Mind Points you spend this way.', 3),
('orator', 'Unexpected Ally', 1, 'You may use an action and spend 1 Fabula Point to choose a non-hostile creature able to hear and understand you. If you do, that creature becomes helpful towards you so long as you are kind and respectful to them and your requests are reasonable.', 4),
('rogue', 'Cheap Shot', 5, 'When you hit a creature with an attack, if the attack only targeted that creature and they are suffering from one or more status effects, you may have it deal extra damage equal to【SL + the number of status effects on the creature】.', 0),
('rogue', 'Dodge', 3, 'As long as you have no shields and no martial armor equipped, your Defense score is increased by【SL】.', 1),
('rogue', 'High Speed', 3, 'At the start of a conflict, you may spend 10 Mind Points. If you do, choose one option and apply it before the start of the first round: perform a free attack with a weapon you have equipped; or perform a Hinder or Objective action. You also gain a bonus equal to【SL】to all Checks you perform as part of the chosen option.', 2),
('rogue', 'See You Later', 1, 'You may use an action and spend 1 Fabula Point to vanish from the current scene, reappearing whenever you want during a different scene in which another Player Character is present. Describe how you escaped and miraculously got here!', 3),
('rogue', 'Soul Steal', 5, 'You may use an action to perform a【DEX + WLP】Check against the Magic Defense of a creature you can see. If you succeed and the target is a soldier, you recover 【SL】Inventory Points; if they are an elite or champion, the GM gives you the target''s soul treasure, an item worth an amount of zenit equal to or lower than 【the target''s level multiplied by 30, or by 50 if they are a Villain】. This soul treasure will appear inside your backpack; a creature can be successfully stolen from with this Skill only once. You gain a bonus equal to【SL】to your 【DEX + WLP】Checks for this Skill.', 4),
('sharpshooter', 'Barrage', 1, 'When you perform a ranged attack, you may spend 10 Mind Points to choose one option: the attack gains multi (2); or you increase the attack''s multi property by one, up to a maximum of multi (3).', 0),
('sharpshooter', 'Crossfire', 1, 'After a creature you can see performs a ranged attack, you may spend an amount of Mind Points equal to the total Result of their Accuracy Check in order to have the attack fail automatically against all targets. You can only use this Skill if you have a ranged weapon equipped, and it has no effect if the Accuracy Check was a critical success.', 1),
('sharpshooter', 'Hawkeye', 5, 'When you perform the Guard action, if you choose not to provide cover to another creature, you may choose one option: the next ranged attack you perform before the end of the current scene will deal【SL × 2】extra damage; or you may immediately perform a free attack with a bow or firearm you have equipped, treating your High Roll (HR) as 0 when calculating damage dealt by this attack.', 2),
('sharpshooter', 'Ranged Weapon Mastery', 4, 'You gain a bonus equal to【SL】to all Accuracy Checks with ranged weapons.', 3),
('sharpshooter', 'Warning Shot', 4, 'When you hit one or more targets with a ranged attack that would deal damage, you may have the attack deal no damage. If you do, choose one option: inflict shaken on each target hit by the attack; or inflict slow on each target hit by the attack; or each target hit by the attack loses【SL × 10】Mind Points. Describe your maneuver!', 4),
('spiritist', 'Healing Power', 2, 'When you cast a spell that targets one or more allies, if you have an arcane weapon equipped, you may have each of those allies recover an amount of Hit Points equal to【SL, multiplied by the number of Bonds you have】. This healing is separate from any healing caused by the effects of the spell.', 0),
('spiritist', 'Ritual Spiritism', 1, 'You may perform Rituals whose effects fall within the Spiritism discipline. Spiritism Rituals use【INS + WLP】for the Magic Check.', 1),
('spiritist', 'Spiritual Magic', 10, 'Each time you acquire this Skill, learn one Spiritist spell (see next two pages). Offensive (r) Spiritist spells use【INS + WLP】for the Magic Check.', 2),
('spiritist', 'Support Magic', 1, 'When you cast a spell that targets one or more allies, if you have an arcane weapon equipped, you may choose one of those allies you have a Bond towards. If you do, that ally gains a bonus to the next Check they perform during the current scene; this bonus is equal to the strength of your Bond towards them.', 3),
('spiritist', 'Vismagus', 1, 'When you cast a spell, if you don''t have enough Mind Points to pay for its total cost, you may choose to spend twice as many Hit Points instead. You cannot use this Skill if doing so would reduce you to 0 Hit Points. If a spell cast this way would cause you to recover Hit Points, you instead recover no Hit Points (the spell functions normally on any other target).', 4),
('tinkerer', 'Emergency Item', 1, 'Once per conflict scene, if you are in Crisis, you may perform an additional action on your turn. This action must be the Inventory action.', 0),
('tinkerer', 'Gadgets', 5, 'When you first acquire this Skill, choose a gadget type: alchemy, infusions or magitech (see next four pages). You gain its basic benefits.

Whenever you take this Skill again, choose one option: you gain the basic benefits of a new gadget type; or you gain the advanced benefits of a gadget type whose basic benefits you already obtained; or you gain the superior benefits of a gadget type whose advanced benefits you already obtained.', 1),
('tinkerer', 'Potion Rain', 2, 'When you create a potion that restores a single creature''s HP and/or MP, you may have it affect up to【SL】additional creatures. If you do, the potion only restores half the normal amount of HP and MP to each creature.', 2),
('tinkerer', 'Secret Formula', 5, 'When you create a potion or magisphere whose effects restore HP and/or MP, each restored amount is increased by【SL × 5】.

When you create an elemental shard, potion or magisphere that deals damage, that item deals【SL】extra damage.', 3),
('tinkerer', 'Visionary', 5, 'When you work on a Project, up to【SL × 100】zenit of material costs are automatically paid; additionally, you generate an additional【SL】progress every day. If multiple characters with this Skill work on the same Project, the effects will be cumulative.', 4),
('wayfarer', 'Faithful Companion', 5, 'Together with the rest of your group, design a level 5 beast, construct, elemental or plant creature (see page 302) that becomes your companion. This creature has no Initiative score and does not level up, can have up to two basic attacks, gains a bonus equal to【SL】to Accuracy Checks and Magic Checks, and their maximum Hit Points are equal to【(SL multiplied by the companion''s base Might die size) + half your level】. Your companion doesn''t get a turn during conflicts, but on your turn you can use an action to have the companion perform an action (only once per turn). If you leave a scene, your companion leaves with you. If your companion falls to 0 Hit Points, they flee and rejoin you at the start of the next scene in which you are present, with HP equal to their Crisis score. When you rest, your companion also gains the full benefits of resting.', 0),
('wayfarer', 'Resourceful', 4, 'You recover【SL】Inventory Points after each travel roll (see page 106).', 1),
('wayfarer', 'Tavern Talk', 3, 'When you rest inside an inn or tavern, you may ask the Game Master up to【SL】questions about your surroundings and the people who live here; the Game Master will answer truthfully and you describe how you gathered the information.', 2),
('wayfarer', 'Treasure Hunter', 2, 'When your group journeys on the world map, you will make a discovery on a roll of 【SL + 1】or lower on the travel roll (instead of only on a 1).', 3),
('wayfarer', 'Well-Traveled', 1, 'You reduce the die rolled for your travel rolls by one size (to a minimum of d6). If multiple characters have this Skill, the effects are not cumulative.', 4),
('weaponmaster', 'Bladestorm', 1, 'When you perform a melee attack, you may spend 10 Mind Points to choose one option: the attack gains multi (2); or you increase the attack''s multi property by one, up to a maximum of multi (3).', 0),
('weaponmaster', 'Bone Crusher', 4, 'When you hit one or more targets with a melee attack that would deal damage, you may have the attack deal no damage. If you do, choose one option: inflict dazed on each target hit by the attack; or inflict weak on each target hit by the attack; or each target hit by the attack loses【SL × 10】Mind Points. Describe your maneuver!', 1),
('weaponmaster', 'Breach', 3, 'You may use an action and spend 5 Mind Points to perform a free attack with a melee weapon you have equipped. This attack must target a single creature. If the attack is successful, it deals no damage and you choose one option: you destroy one shield equipped by the target; or you destroy the target''s equipped armor; or whenever the target suffers damage from a source before the start of your next turn, that source deals【SL × 2】extra damage to them.', 2),
('weaponmaster', 'Counterattack', 1, 'After an enemy hits or misses you with a melee attack, if the Result of their Accuracy Check was an even number, you may perform a free attack against that enemy (after their attack has been fully resolved). This attack must be a melee attack and must have that enemy as its only target; treat your High Roll (HR) as 0 when calculating damage dealt by this attack.', 3),
('weaponmaster', 'Melee Weapon Mastery', 4, 'You gain a bonus equal to【SL】to all Accuracy Checks with melee weapons.', 4)
on conflict (class_id, name) do nothing;

insert into shg_fu_spell (class_id, name, offensive, mp_cost, target, duration, description, opportunity, sort_order) values
('elementalist', 'Elemental Shroud', false, '5 × T', 'Up to three creatures', 'Scene', 'You weave magical energy and protect the targets from the fury of the elements. Choose a damage type: air, bolt, earth, fire or ice. Until this spell ends, each target gains Resistance against the chosen damage type.', null, 0),
('elementalist', 'Elemental Weapon', false, '10', 'One weapon', 'Scene', 'You imbue a weapon with elemental energy. Choose a damage type: air, bolt, earth, fire, or ice. Until this spell ends, all damage dealt by the weapon becomes of the chosen damage type. If you have that weapon equipped while you cast this spell, you may perform a free attack with it as part of the same action. This spell can only be cast on a weapon equipped by a willing creature.', null, 1),
('elementalist', 'Flare', true, '20', 'One creature', 'Instantaneous', 'You channel a single ray of fire towards your foe, its temperature so high that it will pierce through most defenses. The target suffers【HR + 25】fire damage. Damage dealt by this spell ignores Resistances.', null, 2),
('elementalist', 'Fulgur', true, '10 × T', 'Up to three creatures', 'Instantaneous', 'You weave electricity into a wave of crackling bolts. Each target hit by this spell suffers【HR + 15】bolt damage.', 'Each target hit by this spell suffers dazed.', 3),
('elementalist', 'Glacies', true, '10 × T', 'Up to three creatures', 'Instantaneous', 'You coat your foes under a thick layer of frost. Each target hit by this spell suffers【HR + 15】ice damage.', 'Each target hit by this spell suffers slow.', 4),
('elementalist', 'Iceberg', true, '20', 'One creature', 'Instantaneous', 'A pillar of ice magic envelops your foe, suddenly dropping their body temperature to a critical level. The target suffers【HR + 25】ice damage. Damage dealt by this spell ignores Resistances.', null, 5),
('elementalist', 'Ignis', true, '10 × T', 'Up to three creatures', 'Instantaneous', 'You unleash a searing barrage against your foes, conjuring flames out of thin air. Each target hit by this spell suffers【HR + 15】fire damage.', 'Each target hit by this spell suffers shaken.', 6),
('elementalist', 'Soaring Strike', false, '10', 'Self', 'Instantaneous', 'The wind carries your strikes across the battlefield. You may immediately perform a free attack with a melee weapon you have equipped. This attack may target creatures that can only be targeted by ranged attacks. If you used a weapon belonging to the brawling or spear Category for this attack, it deals 5 extra damage. If you hit a flying target with this attack, you may force them to land immediately.', null, 7),
('elementalist', 'Terra', true, '10 × T', 'Up to three creatures', 'Instantaneous', 'Spires of jagged rock erupt from the ground beneath your foes, closing around them. Each target hit by this spell suffers【HR + 15】earth damage. This spell cannot target creatures who are flying, floating, falling, or otherwise in mid-air.', 'Each target hit by this spell performs one fewer action on their next turn (to a minimum of 0 actions).', 8),
('elementalist', 'Thunderbolt', true, '20', 'One creature', 'Instantaneous', 'You send lightning striking at your foe. The target suffers【HR + 25】bolt damage. Damage dealt by this spell ignores Resistances.', null, 9),
('elementalist', 'Ventus', true, '10 × T', 'Up to three creatures', 'Instantaneous', 'You summon the power of winds against your enemy. Each target hit by this spell suffers【HR + 15】air damage.', 'Each flying target hit by this spell is forced to land immediately.', 10),
('elementalist', 'Vortex', false, '10', 'Self', 'Scene', 'A roaring gale surrounds you, blowing away arrows and bullets. Until this spell ends, you gain a +2 bonus to your Defense against ranged attacks.', null, 11),
('entropist', 'Acceleration', false, '20', 'One creature', 'Scene', 'You bend the fabric of time. Until this spell ends, the target gains the ability to perform a single additional action during each of their turns. Once the target has performed a total of two additional actions granted by this spell, this spell ends.', null, 0),
('entropist', 'Anomaly', true, '20', 'One creature', 'Scene', 'You alter the very nature of your target. Until this spell ends, if the target would suffer damage of a type they Absorb or are Immune to, they are instead treated as if they were Vulnerable to that damage type. Once that happens, this spell ends.', null, 1),
('entropist', 'Dark Weapon', false, '10', 'One equipped weapon', 'Scene', 'You imbue a weapon with dark energy. Until this spell ends, all damage dealt by the weapon becomes of the dark type. If you have that weapon equipped while you cast this spell, you may perform a free attack with it as part of the same action. This spell can only be cast on a weapon equipped by a willing creature.', null, 2),
('entropist', 'Dispel', false, '10', 'One creature', 'Instantaneous', 'You release a wave of negative energy and cleanse all magic from a creature. If the target is affected by one or more spells with a duration of Scene, they are no longer affected by any of those spells instead.', null, 3),
('entropist', 'Divination', false, '10', 'Self', 'Scene', 'You glimpse briefly into the future. Until this spell ends, after a creature you can see performs a Check, if it was not a fumble nor a critical success, you may force that creature to reroll both dice. Once you have forced two rerolls this way, this spell ends.', null, 4),
('entropist', 'Drain Spirit', true, '5', 'One creature', 'Instantaneous', 'You consume a creature''s psyche. The target loses【HR + 15】Mind Points. Then, you recover an amount of Mind Points equal to half the Mind Points loss they suffered (if the loss was reduced to 0 in some way, you recover none).', null, 5),
('entropist', 'Drain Vigor', true, '10', 'One creature', 'Instantaneous', 'You steal another creature''s life force. The target suffers【HR + 15】dark damage. Then, you recover an amount of Hit Points equal to half the Hit Points loss they suffered (if the loss was reduced to 0 in some way, you recover none).', null, 6),
('entropist', 'Gamble', false, 'up to 20', 'Special', 'Instantaneous', 'You summon a vortex of chaotic energy. Roll your current Willpower die once for every 10 Mind Points spent while casting this spell, then keep the single die you prefer: the number on that die determines the effects of this spell.

1 You lose half of your current Hit Points and half of your current Mind Points.
2-3 Each creature present on the scene, including yourself, suffers poisoned.
4-6 Each creature present on the scene, including yourself, suffers slow.
7-8 Choose up to three creatures you can see: each of them recovers 50 Hit Points and also recovers from all status effects.
9+ Choose any number of creatures you can see: each of them suffers 30 damage. The damage type is determined randomly by rolling a d6: 1. air   2. bolt   3. dark   4. earth   5. fire   6. poison', null, 7),
('entropist', 'Mirror', false, '10', 'One creature', 'Scene', 'You twist the laws of magic. Until this spell ends, if an offensive (r) spell is cast on the target, the creature who cast that offensive spell will be targeted in their stead (any other targets of the offensive spell will be targeted as normal). Once that happens, this spell ends.', null, 8),
('entropist', 'Omega', true, '20', 'One creature', 'Instantaneous', 'You invoke doom on your foe, turning strength into frailty. The target loses an amount of Hit Points equal to【20 + half the target''s level】.', null, 9),
('entropist', 'Stop', true, '10', 'One creature', 'Instantaneous', 'You trap a foe inside a circle of altered time and space. The target will perform one fewer action on their next turn (to a minimum of 0 actions).', null, 10),
('entropist', 'Umbra', true, '10 × T', 'Up to three creatures', 'Instantaneous', 'A storm of dark energy turns matter into ash. Each target hit by this spell suffers 【HR + 15】dark damage.', 'Each target hit by this spell suffers weak.', 11),
('spiritist', 'Aura', false, '5×T', 'Up to three creatures', 'Scene', 'You project your soul outside your body and direct it to surround the targets, shielding them from dangerous magic. Until this spell ends, each target may treat their Magic Defense as being equal to 12 against any effects that target it (they are still free to use their normal Defense score if higher than 12).', null, 0),
('spiritist', 'Awaken', false, '20', 'One creature', 'Scene', 'You allow a creature to focus their vital energy into accomplishing what they previously could not. Choose one Attribute: Dexterity, Insight, Might, or Willpower. Until this spell ends, the target treats the chosen Attribute as if it were one die size higher (up to a maximum of d12).', null, 1),
('spiritist', 'Barrier', false, '5×T', 'Up to three creatures', 'Scene', 'You project your soul outside your body and weave it into a barrier to protect the targets from attacks. Until this spell ends, each target may treat their Defense as being equal to 12 against any effects that target it (they are still free to use their normal Defense score if higher than 12).', null, 2),
('spiritist', 'Cleanse', false, '5×T', 'Up to three creatures', 'Instantaneous', 'You strengthen and purify the soul energy coursing through your companions. Each target recovers from all status effects.', null, 3),
('spiritist', 'Enrage', true, '10', 'One creature', 'Instantaneous', 'You cause a creature to lose any semblance of temper and act brazenly. The target suffers enraged and cannot perform the Guard or Spell actions during their next turn.', null, 4),
('spiritist', 'Hallucination', true, '5×T', 'Up to three creatures', 'Instantaneous', 'You alter the senses of your enemies, causing them to experience bizarre or frightening hallucinations. Choose dazed or shaken: you inflict the chosen status effect on each target hit by this spell.', null, 5),
('spiritist', 'Heal', false, '10 × T', 'Up to three creatures', 'Instantaneous', 'You invigorate your companions, soothing their pain and healing their fatigue. Each target recovers 40 Hit Points. This amount increases to 50 Hit Points if you are level 20 or higher, or to 60 Hit Points if you are level 40 or higher.', null, 6),
('spiritist', 'Lux', true, '10 × T', 'Up to three creatures', 'Instantaneous', 'You focus your inner energy into a barrage of blinding soul rays. Each target hit by this spell suffers【HR + 15】light damage.', 'Each target hit by this spell suffers dazed.', 7),
('spiritist', 'Mercy', false, '20', 'One creature', 'Scene', 'You strengthen the heart of a creature against suffering and despair. Until this spell ends, if the target would be reduced to 0 Hit Points, they are instead left standing with exactly 1 Hit Point. Once that happens, this spell ends.', null, 8),
('spiritist', 'Reinforce', false, '5×T', 'Up to three creatures', 'Scene', 'You protect the targets from attacks that would corrupt their body and spirit. Choose dazed, enraged, poisoned, shaken, slow, or weak. Until this spell ends, each target becomes immune to the chosen status effect.', null, 9),
('spiritist', 'Soul Weapon', false, '10', 'One equipped weapon', 'Scene', 'You imbue a weapon with the cleansing energy of your spirit. Until this spell ends, all damage dealt by the weapon becomes of the light type. If you have that weapon equipped while you cast this spell, you may perform a free attack with it as part of the same action. This spell can only be cast on a weapon equipped by a willing creature.', null, 10),
('spiritist', 'Torpor', true, '5×T', 'Up to three creatures', 'Instantaneous', 'You smother the soul energy coursing through the bodies of your foes, hindering their movements. Choose slow or weak: you inflict the chosen status effect on each target hit by this spell.', null, 11)
on conflict (class_id, name) do nothing;

insert into shg_fu_arcanum (class_id, name, domains, merge_effect, dismiss_effect, sort_order) values
('arcanist', 'Arcanum of the Forge', ARRAY['fire', 'heat', 'metal']::text[], 'You have Resistance to fire damage. Any fire damage you deal ignores Resistances.', 'When you dismiss this Arcanum, choose Forge or Inferno: Forge. You create a basic armor, shield or weapon of your choice (see pages 130 to 133). If you select this option again, the previously created item vanishes. If you create a weapon this way, it deals fire damage instead of physical. Inferno. Choose any number of creatures you can see: each of them suffers 30 fire damage. This damage ignores Resistances.', 0),
('arcanist', 'Arcanum of the Frost', ARRAY['cold', 'ice', 'silence']::text[], 'You have Resistance to ice damage and are immune to enraged. Any ice damage you deal ignores Resistances.', 'Ice Age. Choose any number of creatures you can see: each of them suffers 30 ice damage. This damage ignores Resistances.', 1),
('arcanist', 'Arcanum of the Gate', ARRAY['space', 'travel', 'void']::text[], 'You have Resistance to dark damage. You gain a +1 bonus to your Magic Defense.', 'When you dismiss this Arcanum, choose Oblivion or Warp: Oblivion. Choose any number of creatures you can see: each of them suffers 30 dark damage. This damage ignores Resistances. Warp. You teleport yourself and up to five other nearby willing creatures to a location you previously visited, if that location is within 1 travel day.', 2),
('arcanist', 'Arcanum of the Grimoire', ARRAY['knowledge', 'revelations', 'understanding']::text[], 'You are able to read, write, speak and understand all languages. You treat your Insight as if it were one die size higher (up to a maximum of d12).', 'Oracle. You ask the Game Master a single question. The Game Master must answer truthfully, describing the vision shown to you by the Grimoire. Once used, this dismiss effect will not be available until the next dawn. Furthermore, the same question may never be asked more than once. The Game Master has final say on which questions are too similar to be asked again.', 3),
('arcanist', 'Arcanum of the Oak', ARRAY['earth', 'plants', 'poison']::text[], 'You have Resistance to earth and poison damage and are immune to poisoned. Whenever you recover Hit Points, you recover 5 extra Hit Points.', 'Blossom. Choose any number of creatures you can see (you may also choose yourself): each of them recovers from the poisoned status effect and recovers 40 Hit Points. This amount increases to 50 Hit Points if you are level 20 or higher, or to 60 Hit Points if you are level 40 or higher.', 4),
('arcanist', 'Arcanum of the Sky', ARRAY['fog', 'rain', 'storms']::text[], 'You have Resistance to air and bolt damage. You may use an action to accurately predict weather conditions for the next day within a range of two travel days — the Game Master will tell you what the weather conditions will be.', 'Thunderstorm. Choose any number of creatures you can see: each of them suffers 30 bolt damage. This damage ignores Resistances.', 5),
('arcanist', 'Arcanum of the Sword', ARRAY['conquest', 'heroism', 'leadership']::text[], 'Your attacks deal 5 extra damage, and all damage dealt by your attacks is treated as having no type (thus being unaffected by damage Affinities). Damage dealt by your attacks cannot gain a type as long as you are merged with this Arcanum. When you perform an attack, you may have that attack gain the multi (any number of targets) property. If you do, this Arcanum will be automatically dismissed after the attack is resolved (this is not considered a willing dismiss).', '', 6),
('arcanist', 'Arcanum of the Tower', ARRAY['judgment', 'protection', 'sacrifice']::text[], 'When you summon this Arcanum, choose a damage type: air, bolt, dark, earth, fire, or ice. Until this Arcanum is dismissed, each of your allies present on the scene has Resistance to the chosen damage type (you do not gain this Resistance).', 'Judgment. Choose any number of creatures you can see: each of them suffers 30 light damage. This damage ignores Resistances.', 7),
('arcanist', 'Arcanum of the Wheel', ARRAY['destiny', 'speed', 'time']::text[], 'You are immune to slow. You gain a +1 bonus to your Defense.', 'Time Freeze. Choose any number of creatures you can see: each of them suffers slow. If a creature chosen this way is already slow, that creature will instead perform one fewer action during their next turn (to a minimum of 0 actions).', 8)
on conflict (class_id, name) do nothing;

insert into shg_fu_invention_type (id, class_id, name, also_known_as, description, tiers, sort_order) values
('tinkerer-alchemy', 'tinkerer', 'Alchemy', ARRAY['Chemistry', 'Bombs', 'Mutations']::text[], 'You may perform the Inventory action to rapidly craft a potion with powerful but somewhat unpredictable effects. When you do so, choose one type of mix among those you have unlocked (basic, advanced or superior) and spend the appropriate amount of Inventory Points.', '[{"tier":"basic","ipCost":3,"text":"Roll two d20s and assign one to target and one to effect."},{"tier":"advanced","ipCost":4,"text":"Roll three d20s and assign one to target and one to effect."},{"tier":"superior","ipCost":5,"text":"Roll four d20s and assign one to target and one to effect."},{"tier":"basic","name":"Target Table","text":"When you create a mix, roll the amount of twenty-sided dice indicated by that mix, then assign one of those rolls to the target table (below) and one to the effect table (on the right). Discard all remaining dice, then describe the effects of the mix!\n\nWant to craft airships, golems, sleep potions and more? See Projects, on page 136!","table":{"headers":["Die","The potion affects..."],"rows":[["1-6","... you or one ally you can see that is present on the scene."],["7-11","... one enemy you can see that is present on the scene."],["12-16","... you and every ally present on the scene."],["17-20","... every enemy present on the scene."]]}},{"tier":"basic","name":"Effect Table","text":"Example: You spend 5 Inventory Points for a superior mix and roll four twenty-sided dice. You roll 3, 14, 9 and 4. You might assign 14 to target and 9 to effect to grant yourself and all allies Resistance to air and fire; or you could go on the offensive and assign 9 to target and 4 to effect to deal bolt damage to a single enemy; or even assign 9 to target and 14 to effect to inflict four status effects on that foe! Whatever your choice, the two dice you don''t assign will be discarded.\n\nThe two effects marked with \"Any\" on the effect table are always available and can be chosen if none of the available effects appeal to you.","table":{"headers":["Die","Each creature affected by the potion..."],"rows":[["Any","... suffers 20 poison damage."],["Any","... recovers 30 Hit Points."],["1","... treats their Dexterity and Might dice as if they were one size higher (up to a maximum of d12) until the end of your next turn."],["2","As effect 1, but with Insight and Willpower."],["3","... suffers 20 air damage. This amount increases to 30 damage if you are level 20 or higher, or to 40 damage if you are level 40 or higher."],["4","As effect 3, but with bolt damage."],["5","As effect 3, but with dark damage."],["6","As effect 3, but with earth damage."],["7","As effect 3, but with fire damage."],["8","As effect 3, but with ice damage."],["9","... gains Resistance to air and fire damage until the end of the scene."],["10","As effect 9, but with bolt and ice damage."],["11","As effect 9, but with dark and earth damage."],["12","... suffers enraged."],["13","... suffers poisoned."],["14","... suffers dazed, shaken, slow and weak."],["15","... recovers from all status effects."],["16-17","... recovers 50 Hit Points and 50 Mind Points."],["18","... recovers 100 Hit Points."],["19","... recovers 100 Mind Points."],["20","... recovers 100 Hit Points and 100 Mind Points."]]}}]'::jsonb, 0),
('tinkerer-infusions', 'tinkerer', 'Infusions', ARRAY['Arcane Ammunition', 'Blade Coatings', 'Combat Runes']::text[], 'When you successfully hit one or more targets with an attack, you may spend 2 Inventory Points to produce a special infusion and apply the corresponding effect to that attack (if the attack had the multi property, apply the effects of the infusion to each target).

You cannot apply more than one infusion to the same attack; producing and using an infusion are both part of the action you used to attack with the weapon.', '[{"tier":"basic","name":"Cryo","text":"The attack deals 5 extra damage, and its damage becomes ice."},{"tier":"basic","name":"Pyro","text":"The attack deals 5 extra damage, and its damage becomes fire."},{"tier":"basic","name":"Volt","text":"The attack deals 5 extra damage, and its damage becomes bolt."},{"tier":"advanced","name":"Cyclone","text":"The attack deals 5 extra damage, and its damage becomes air."},{"tier":"advanced","name":"Exorcism","text":"The attack deals 5 extra damage, and its damage becomes light."},{"tier":"advanced","name":"Seismic","text":"The attack deals 5 extra damage, and its damage becomes earth."},{"tier":"advanced","name":"Shadow","text":"The attack deals 5 extra damage, and its damage becomes dark."},{"tier":"superior","name":"Vampire","text":"Choose one option: you recover an amount of HP equal to half the HP loss suffered by the target of the attack; or you recover an amount of MP equal to half the HP loss suffered by the target of the attack. This infusion can only be used if the attack targeted a single creature."},{"tier":"superior","name":"Venom","text":"The attack deals 5 extra damage, its damage becomes poison, and each creature hit by the attack suffers poisoned."}]'::jsonb, 1),
('tinkerer-magitech', 'tinkerer', 'Magitech', ARRAY['Engineering', 'Golemcraft', 'Robotics']::text[], 'This invention type grants a variety of different benefits.', '[{"tier":"basic","name":"Magitech Override","text":"You may use an action and spend 10 Mind Points to perform an Opposed 【INS + INS】Check against a nearby soldier-rank construct you can see (the Game Master must tell you who is a valid target). If you succeed, you gain control of the creature until the end of the scene (the Game Master gives you its profile). You may only control one construct at any given time, but may set it free whenever you want; the construct is also set free as soon as it is harmed by you or by one of your allies. Once free, the construct is again in control of its actions and might turn against you."},{"tier":"advanced","name":"Magicannon","ipCost":3,"text":"You may perform the Inventory action and spend 3 Inventory Points to create a firearm weapon known as a magicannon (see below). The magicannon will crumble to pieces as soon as you use create a new magicannon. When you create a magicannon, choose the type of damage it deals (air, bolt, earth, fire, ice, or physical).\n\nMagicannon — 【DEX + INS】+1 accuracy, 【HR + 10】damage. Two-handed, Ranged, No Quality."},{"tier":"superior","name":"Magispheres","ipCost":2,"text":"You develop three magisphere prototypes; each of them can replicate a spell chosen from the following lists: Elementalist, Entropist and Spiritist. The spells you choose may come from the same list or different lists.\n\nYou also develop two more prototypes upon reaching level 20, and another two upon reaching level 40 (the same applies if you already reached those levels).\n\nYou may perform the Inventory action and spend 2 Inventory Points to create a magisphere and immediately perform the Spell action for free, casting one of the spells you have developed a prototype for. The spell follows the normal rules (including MP costs and Magic Checks) and the magisphere is destroyed upon use."}]'::jsonb, 2)
on conflict (id) do nothing;

