insert into shg_fu_heroic_skill (id, name, requirement, description, sort_order) values
('adversity', 'Adversity', 'You must have mastered the Darkblade Class', 'As long as you are suffering from one or more status effects, you gain a +1 bonus on all Checks for every status effect you are suffering from, and you deal 2 extra damage for every status effect you are suffering from (be it with attacks, spells, Arcana, items or any other method).', 0),
('ambidextrous', 'Ambidextrous', null, 'You may apply the benefits of two-weapon fighting (page 69) to weapons belonging to different categories, even if one is a melee weapon and the other is a ranged weapon (such as a dagger and a firearm, for instance).', 1),
('arcane-echoes', 'Arcane Echoes', 'You must have mastered the Arcanist Class', 'When you successfully perform a Check to fill or erase one or more sections of a Clock, if the domains of one or more Arcana you have bound are applicable to the Check in question, you may fill or erase an additional section of that Clock. The Game Master has final say on whether a given domain applies or not.', 2),
('chimeric-mastery', 'Chimeric Mastery', 'You must have mastered the Chimerist Class', 'Choose two creature Species among construct, demon, elemental, and undead. You can now use spell mimic to learn spells from creatures of the chosen Species. This Heroic Skill may be acquired up to twice, each time selecting two Species from the list above. Whenever you acquire this Skill, you also increase your upper limit for memorized Chimerist spells by 2.', 3),
('comet', 'Comet', 'You must have mastered the Entropist Class', 'You learn the ultimate Entropist spell: Comet. Comet MP: 50 Target: Special Duration: Instantaneous You rip open a large portal to the Cosmos, calling down astral debris from the gaping void. Choose on option: one creature you can see suffers 60 damage; or you choose any number of creatures you can see, and each of them suffers 40 damage. These amounts increase by 5 if you are level 20 or higher, or by 10 if you are level 40 or higher. Damage dealt by this spell has no type (thus being unaffected by damage Affinities).', 4),
('deep-pockets', 'Deep Pockets', 'You must have mastered the Tinkerer Class', 'When you spend Inventory Points, you spend 1 less Inventory Point (minimum 1).', 5),
('disarming-rhetoric', 'Disarming Rhetoric', 'You must have mastered the Orator Class', 'During a conflict scene, you may use an action and choose a soldier-rank creature that can hear and understand you (the Game Master must tell you who is a valid target). If that creature is shaken or in Crisis, you may spend an amount of Mind Points equal to 【20 + half that creature''s level】to have them peacefully leave the conflict. Describe how you convince them to desist.', 6),
('extra-hp', 'Extra HP', null, 'Permanently increase your maximum Hit Points by 10. The amount of additional HP increases to 20 if you are level 40 or higher.', 7),
('extra-ip', 'Extra IP', null, 'Permanently increase your maximum Inventory Points by 4.', 8),
('extra-mp', 'Extra MP', null, 'Permanently increase your maximum Mind Points by 10. The amount of additional MP increases to 20 if you are level 40 or higher.', 9),
('extra-spells', 'Extra Spells', null, 'When you acquire this Skill, learn any two spells from one of the following lists: Elementalist, Entropist, or Spiritist. Both spells chosen this way must come from the same list, and they follow the standard rules for casting spells of that Class.', 10),
('heartbreaker', 'Heartbreaker', 'You must have mastered the Darkblade Class', 'When you hit a creature with an attack, if that attack only targeted that creature and you have a Bond towards them, you may choose to spend half of your current Hit Points, rounded down. If you do, the attack deals extra damage equal to【10 multiplied by the strength of your Bond towards the target】. You may use this Skill only on your turn during a conflict, and only once per turn.', 11),
('heroic-companion', 'Heroic Companion', 'You must have mastered the Wayfarer Class, and must have acquired the Faithful Companion Skill', 'Your bond with your companion grows stronger. You gain the following benefits: w The companion''s maximum Hit Points increase by 10. w Choose one of the companion''s Attributes: Dexterity, Insight, Might, or Willpower. The chosen Attribute is permanently increased by one die size (up to a maximum size of d12). w The companion gains an additional Skill. When you reach level 40, or if you have already reached it, the companion gains an additional Skill. Make sure to discuss your Skill W choices with the Game Master and the other Players.', 12),
('hope', 'Hope', 'You must have mastered the Spiritist Class', 'You learn the ultimate Spiritist spell: Hope. Hope MP: 40 Target: Special Duration: Instantaneous You rekindle the flames of courage and hope within a defeated hero. Choose a Player Character who surrendered but is still present on the scene: that Player Character immediately regains consciousness and recovers an amount of Hit Points equal to their Crisis score. Note that this spell will not undo the consequences of the character''s surrender and is of no use if the character left the scene as part of their surrender — such as if they were captured and dragged away, or if they were trapped in a parallel dimension, and so on. A Player Character may only be affected by this spell once per scene; if a character is brought back into the conflict by this spell and is subsequently reduced to 0 Hit Points again, they must sacrifice themselves or surrender as per the normal rules (including a new consequence and 2 more Fabula Points if they surrender).', 13),
('mathemagic', 'Mathemagic', 'You must have mastered the Loremaster Class', 'When you cast a spell with a target of "One creature", you may double the spell''s total MP cost. If you do, choose an Attribute (Dexterity, Insight, Might, or Willpower) and a die size (d6, d8, d10 or d12). The spell now targets all creatures present on the scene whose current Attribute die size matches your choice, regardless of whether they are friends or foes (you might even end up targeting yourself). The effects of the spell are fully applied to every target. If the spell is an offensive (r) spell, it follows the normal rules: you perform a single Magic Check and confront it with the Magic Defense of each target to determine who is hit by the spell.', 14),
('monkey-grip', 'Monkey Grip', 'You must have mastered the Fury Class', 'You may equip two-handed weapons belonging to the flail, heavy, spear, or sword Categories in a single hand slot. This allows you, for instance, to enjoy the benefits of two-weapon fighting (page 69) while wielding a pair of two-handed weapons, or to equip a two-handed weapon in your main hand slot and a shield in your off-hand slot.', 15),
('perfect-aim', 'Perfect Aim', 'You must have mastered the Sharpshooter Class, and must have acquired the Warning Shot Skill', 'When you hit one or more creatures with a ranged attack and choose to deal no damage in order to gain the benefits of the Warning Shot Skill, you may choose two options instead of one (for instance, you could inflict both shaken and slow on each creature, or inflict a status effect on each creature while also lowering their Mind Points).', 16),
('pillage', 'Pillage', 'You must have mastered the Rogue Class, and must have acquired the Soul Steal Skill', 'When you use the Soul Steal Skill, you may target any number of creatures at the same time (you perform a single Check and compare it to the Magic Defense of each creature you are attempting to steal from).', 17),
('powerful-shot', 'Powerful Shot', 'You must have mastered the Sharpshooter Class', 'When you hit one or more creatures with a ranged attack, that attack deals 5 extra damage to each creature. The amount of extra damage increases to 10 if you are level 40 or higher. "Rest now, sister. For too long I asked you to protect me. Today, it is I who shall be strong for the both of us."', 18),
('powerful-spell', 'Powerful Spell', 'You must have mastered one or more Classes among the following: Chimerist, Elementalist, Entropist, or Spiritist', 'When you cast a spell that deals damage to one or more creatures, that spell deals 5 extra damage to each creature. The amount of extra damage increases to 10 if you are level 40 or higher.', 19),
('powerful-strike', 'Powerful Strike', 'You must have mastered one or more Classes among the following: Fury or Weaponmaster', 'When you hit one or more creatures with a melee attack, that attack deals 5 extra damage to each creature. The amount of extra damage increases to 10 if you are level 40 or higher.', 20),
('predictable', 'Predictable!', 'You must have mastered the Loremaster Class', 'During a conflict, you may use an action and spend 20 Mind Points to anticipate the upcoming moves of a creature you can see, as long as you know two or more of that creature''s Traits. If you do so, choose one type of action among the following: Attack, Guard, Objective, Spell, or Skill. Until the start of your next turn, the creature must spend 20 Mind Points whenever they wish to perform that action. If they can''t, they must perform a different action.', 21),
('rampart', 'Rampart', 'You must have mastered the Guardian Class', 'During the first round of each conflict scene, you have Resistance to all damage types and cannot suffer status effects (you do not recover from preexisting status effects, however). These benefits only last until the end of the first round.', 22),
('repetition', 'Repetition', 'You must have mastered the Orator Class', 'Once per turn during a conflict, after you use the Condemn Skill or the Encourage Skill, you may immediately perform that same Skill again (on the same target or a different one). You must still pay the Mind Point cost for the second use of the Skill.', 23),
('revelation', 'Revelation', 'You must have mastered the Arcanist Class', 'You make contact with an unknown Arcanum and bind it to your soul. This Arcanum must be something you design together with the rest of the group; as long as you live, no one else in your world will be able to bind that Arcanum. Once per scene while you are merged with an Arcanum, you may use an action and spend 2 Fabula Points to trigger that Arcanum''s dismiss effect (if any) without dismissing them. Doing so does not trigger the Arcane Circle Skill (page 177).', 24),
('status-immunity', 'Status Immunity', 'You must have mastered the Wayfarer Class', 'You become completely immune to a single status effect of your choice.', 25),
('tempest-strike', 'Tempest Strike', 'You must have mastered the Weaponmaster Class', 'When you perform a melee attack with the multi property, if you choose to target only one creature, the attack deals 5 extra damage if the attack had multi (2), or 10 extra damage if the attack had multi (3 or higher).', 26),
('unbreakable', 'Unbreakable', 'You must have mastered the Guardian Class', 'Once per scene when you are about to be reduced to 0 Hit Points, you may instead choose to withstand the pain and be reduced to exactly 1 Hit Point.', 27),
('upgrade', 'Upgrade', 'You must have mastered the Tinkerer Class', 'Once per rest, you may choose one option: add a Quality to a single weapon, armor, or shield that doesn''t have one; or replace the current Quality of a single weapon, armor, or shield with a different Quality. When you use this Skill, you must select a Quality from the default list for that item type as long as the cost modifier associated with that ability is +1000 zenit or lower. Then, you must spend an amount of zenit equal to twice the cost modifier of the chosen ability. The modified item will be ready at the end of the rest; you may only modify one item per rest. The default list of weapon abilities can be found on page 269, while the default list of armor and shield abilities can be found on page 280.', 28),
('vanish', 'Vanish', 'You must have mastered the Rogue Class', 'When you hit one or more creatures with an attack, you may spend 1 Fabula Point. If you do, each of those creatures will be unable to perform any action that requires them to be able to see you until the start of your next turn.', 29),
('volcano', 'Volcano', 'You must have mastered the Elementalist Class', 'You learn the ultimate Elementalist spell: Volcano. Volcano MP: 40 Target: Special Duration: Instantaneous You channel the fury of the planet into a powerful wave of fire and magma. Choose one option: one creature you can see suffers 50 fire damage; or you choose any number of creatures you can see, and each of them suffers 30 fire damage. These amounts increase by 5 if you are level 20 or higher, or by 10 if you are level 40 or higher. Damage dealt by this spell ignores Resistances and Immunities.', 30)
on conflict (id) do nothing;

insert into shg_fu_ritual_discipline (id, name, magic_check, example_uses, sort_order) values
('arcanism', 'Arcanism', 'WLP + WLP', 'Produce a magical effect based on the Arcana you have bound.', 0),
('chimerism', 'Chimerism', 'INS + WLP or MIG + WLP', 'Enhance your senses, see through the eyes of an animal, quell the fury of a monster.', 1),
('elementalism', 'Elementalism', 'INS + WLP', 'Walk on water, shape rock, snuff out fires, cause a rainstorm or summon powerful cyclones.', 2),
('entropism', 'Entropism', 'INS + WLP', 'Cause the decay of physical matter, twist the flow of time, teleport creatures or items.', 3),
('ritualism', 'Ritualism', 'INS + WLP', 'Extract magic from an object, activate a soul circuit, sense the presence of magic.', 4),
('spiritism', 'Spiritism', 'INS + WLP', 'Sense the presence and feelings of creatures, put someone to sleep or embolden their heart.', 5)
on conflict (id) do nothing;

